import{D as e}from"./index-BbvXgB4H.js";var t=`docs/references/hsk/sources/hsk3.pdf`,n=(e,n)=>`${t}#printed-pages=${e}&pdf-pages=${n}`,r=n(`47-55`,`59-67`),i=t=>({image:e(`/assets/group3/lesson-hsk3-l6-${t}-v1.webp`),imageSrcSet:`${e(`/assets/group3/lesson-hsk3-l6-${t}-720w-v1.webp`)} 720w, ${e(`/assets/group3/lesson-hsk3-l6-${t}-v1.webp`)} 1400w`}),a=(e,t)=>({...t,reading:t.reading||t.pinyin,sourceRef:e}),o={liWen:{hanzi:`李文`,pinyin:`Lǐ Wén`,nameTh:`หลี่เหวิน`,nameEn:`Li Wen`,...i(`tickets`),imageFocus:`34% center`},bai:{hanzi:`白家月`,pinyin:`Bái Jiāyuè`,nameTh:`ไป๋เจียเยว่`,nameEn:`Bai Jiayue`,...i(`tickets`),imageFocus:`66% center`},liu:{hanzi:`刘明`,pinyin:`Liú Míng`,nameTh:`หลิวหมิง`,nameEn:`Liu Ming`,...i(`drive`),imageFocus:`34% center`}},s=[[1,`该`,`gāi`,`mod.`,`should`,`ควร / ถึงเวลาที่ต้อง`,48,60],[2,`打算`,`dǎsuàn`,`v./n.`,`plan; intention`,`วางแผน / แผน`,48,60],[3,`高铁`,`gāotiě`,`n.`,`high-speed train`,`รถไฟความเร็วสูง`,48,60],[4,`行`,`xíng`,`v./adj.`,`be all right; capable`,`ได้ / ใช้ได้`,48,60],[5,`路口`,`lùkǒu`,`n.`,`intersection; crossing`,`ทางแยก`,50,62],[6,`小心`,`xiǎoxīn`,`v./adj.`,`take care; careful`,`ระวัง`,50,62],[7,`迟到`,`chídào`,`v.`,`be late`,`มาสาย`,50,62],[8,`红绿灯`,`hóng-lǜdēng`,`n.`,`traffic lights`,`ไฟจราจร`,50,62],[9,`后来`,`hòulái`,`n.`,`afterward; later`,`ต่อมา`,50,62],[10,`急`,`jí`,`adj./v.`,`urgent; be anxious`,`รีบ / ร้อนใจ`,50,62],[11,`如果`,`rúguǒ`,`conj.`,`if`,`ถ้าหาก`,50,62],[12,`以前`,`yǐqián`,`n.`,`earlier times; before`,`ก่อนหน้านี้`,50,62],[13,`耳机`,`ěrjī`,`n.`,`earphones; headphones`,`หูฟัง`,51,63],[14,`充电宝`,`chōngdiànbǎo`,`n.`,`power bank`,`พาวเวอร์แบงก์`,51,63],[15,`常用`,`chángyòng`,`adj.`,`commonly used`,`ใช้เป็นประจำ`,51,63],[16,`越`,`yuè`,`adv.`,`the more... the more...`,`ยิ่ง...ยิ่ง...`,51,63],[17,`分开`,`fēnkāi`,`v.`,`separate`,`แยกจากกัน`,51,63],[18,`检查`,`jiǎnchá`,`v.`,`check; inspect`,`ตรวจสอบ`,51,63],[19,`刷`,`shuā`,`v.`,`scan`,`สแกน`,51,63],[20,`检票`,`jiǎnpiào`,`v.`,`check or inspect tickets`,`ตรวจตั๋ว`,51,63],[21,`电梯`,`diàntī`,`n.`,`elevator; escalator`,`ลิฟต์ / บันไดเลื่อน`,51,63],[22,`放假`,`fàngjià`,`v.`,`have a vacation`,`หยุดเรียน / หยุดงาน`,53,65],[23,`沙发`,`shāfā`,`n.`,`sofa`,`โซฟา`,53,65],[24,`安静`,`ānjìng`,`adj.`,`quiet`,`เงียบสงบ`,53,65],[25,`选择`,`xuǎnzé`,`v.`,`choose`,`เลือก`,53,65],[26,`必须`,`bìxū`,`adv.`,`have to; must`,`ต้อง`,53,65]].map(([e,t,r,i,a,o,s,c])=>({index:e,hanzi:t,pinyin:r,type:i,en:a,th:o,thAid:o,page:s,translationKind:`editorial-aid`,sourceRef:n(String(s),String(c))})),c=n(`48`,`60`),l=n(`49-50`,`61-62`),u=n(`51`,`63`),d=[{id:`h3l6-tickets`,number:`01`,glyph:`铁`,title:`商量坐高铁去上海`,titleTh:`วางแผนนั่งรถไฟความเร็วสูงไปเซี่ยงไฮ้`,titleEn:`Planning a high-speed train trip`,place:`咖啡厅`,placeTh:`ร้านกาแฟ`,...i(`tickets`),imageAlt:{th:`หลี่เหวินกับไป๋เจียเยว่คุยเรื่องรถไฟความเร็วสูง`,zh:`高铁出行场景`,en:`High-speed train planning`},source:`Text 1 · หน้าเล่ม 48 · PDF หน้า 60`,sourcePage:`48`,sourceRef:c,context:`在咖啡厅里，李文和白家月在聊天儿。`,contextTh:`ในร้านกาแฟ หลี่เหวินกับไป๋เจียเยว่กำลังคุยกัน`,contextEn:`In the café, Li Wen and Bai Jiayue were chatting.`,characters:[{role:`A`,profile:`liWen`,noteTh:`ผู้เตือนให้ซื้อตั๋วและช่วยซื้อผ่านแอป`,noteZh:`提醒买票并用手机帮助购票的人`,noteEn:`The person reminding and helping buy tickets`},{role:`B`,profile:`bai`,noteTh:`ผู้ที่อยากลองนั่งรถไฟความเร็วสูง`,noteZh:`想第一次坐高铁的人`,noteEn:`The first-time high-speed train passenger`}],lines:[a(c,{role:`A`,speaker:`李文`,hanzi:`家月，咱们该买去上海的票了。你打算怎么去上海？`,pinyin:`Jiāyuè, zánmen gāi mǎi qù Shànghǎi de piào le. Nǐ dǎsuàn zěnme qù Shànghǎi?`,en:`Jiayue, it’s time to buy our tickets to Shanghai. How do you plan to go?`,th:`เจียเยว่ ถึงเวลาซื้อตั๋วไปเซี่ยงไฮ้แล้ว เธอวางแผนจะไปอย่างไร?`,visual:{zh:`该买票了`,th:`ถึงเวลาซื้อตั๋วแล้ว`,focus:`34% center`}}),a(c,{role:`B`,speaker:`白家月`,hanzi:`我还没坐过高铁，咱们坐高铁去，怎么样？`,pinyin:`Wǒ hái méi zuòguo gāotiě, zánmen zuò gāotiě qù, zěnmeyàng?`,en:`I haven’t taken a high-speed train yet. How about going by high-speed train?`,th:`ฉันยังไม่เคยนั่งรถไฟความเร็วสูง เรานั่งรถไฟความเร็วสูงไปดีไหม?`,visual:{zh:`还没坐过高铁`,th:`ยังไม่เคยนั่งรถไฟความเร็วสูง`,focus:`66% center`}}),a(c,{role:`A`,speaker:`李文`,hanzi:`没问题，从北京到上海的高铁很多，非常方便。`,pinyin:`Méi wèntí, cóng Běijīng dào Shànghǎi de gāotiě hěn duō, fēicháng fāngbiàn.`,en:`No problem. There are many high-speed trains from Beijing to Shanghai, so it’s very convenient.`,th:`ไม่มีปัญหา รถไฟความเร็วสูงจากปักกิ่งไปเซี่ยงไฮ้มีหลายขบวน สะดวกมาก`,visual:{zh:`非常方便`,th:`สะดวกมาก`,focus:`36% center`}}),a(c,{role:`B`,speaker:`白家月`,hanzi:`行！怎么买高铁票？`,pinyin:`Xíng! Zěnme mǎi gāotiěpiào?`,en:`Great! How do we buy high-speed train tickets?`,th:`ได้! ซื้อตั๋วรถไฟความเร็วสูงอย่างไร?`,visual:{zh:`怎么买高铁票`,th:`ซื้อตั๋วอย่างไร`,focus:`64% center`}}),a(c,{role:`A`,speaker:`李文`,hanzi:`用手机App就能买。给我你的护照，我帮你买。`,pinyin:`Yòng shǒujī App jiù néng mǎi. Gěi wǒ nǐ de hùzhào, wǒ bāng nǐ mǎi.`,en:`You can buy them with a mobile app. Give me your passport and I’ll help you.`,th:`ใช้แอปในมือถือก็ซื้อได้ เอาหนังสือเดินทางให้ฉัน ฉันช่วยซื้อให้`,visual:{zh:`用手机App就能买`,th:`ใช้แอปมือถือก็ซื้อได้`,focus:`38% center`}}),a(c,{role:`B`,speaker:`白家月`,hanzi:`早就听说过高铁，终于可以坐上了。`,pinyin:`Zǎo jiù tīngshuoguo gāotiě, zhōngyú kěyǐ zuòshang le.`,en:`I heard about high-speed trains long ago, and finally I get to ride one.`,th:`ได้ยินเรื่องรถไฟความเร็วสูงมานาน ในที่สุดก็ได้นั่งแล้ว`,visual:{zh:`终于可以坐上了`,th:`ในที่สุดก็ได้นั่ง`,focus:`62% center`}}),a(c,{role:`A`,speaker:`李文`,hanzi:`高铁又快又舒服，你一定会喜欢的。`,pinyin:`Gāotiě yòu kuài yòu shūfu, nǐ yídìng huì xǐhuan de.`,en:`High-speed trains are fast and comfortable. You’ll definitely like them.`,th:`รถไฟความเร็วสูงทั้งเร็วทั้งสบาย เธอต้องชอบแน่`,visual:{zh:`又快又舒服`,th:`ทั้งเร็วทั้งสบาย`,focus:`40% center`}})],qte:{after:4,prompt:{th:`หลี่เหวินจะใช้ข้อมูลอะไรช่วยซื้อตั๋วให้?`,zh:`李文要用什么帮助白家月买票？`,en:`What does Li Wen need to help buy the ticket?`},options:[{value:`护照`,zh:`护照`,pinyin:`hùzhào`,th:`หนังสือเดินทาง`},{value:`耳机`,zh:`耳机`,pinyin:`ěrjī`,th:`หูฟัง`},{value:`信用卡`,zh:`信用卡`,pinyin:`xìnyòngkǎ`,th:`บัตรเครดิต`}],correct:`护照`,evidence:`李文：给我你的护照，我帮你买。`,evidenceTh:`หลี่เหวิน: เอาหนังสือเดินทางให้ฉัน ฉันช่วยซื้อให้`,sourceRef:c},builder:{prompt:{th:`เรียงประโยคบอกว่าถึงเวลาซื้อตั๋ว`,zh:`重组“该……了”句`,en:`Rebuild the 该……了 sentence`},answer:[`咱们`,`该`,`买`,`去上海的票`,`了`],tiles:[`去上海的票`,`了`,`该`,`咱们`,`买`],gloss:{咱们:`พวกเรา`,该:`ควร / ถึงเวลา`,买:`ซื้อ`,去上海的票:`ตั๋วไปเซี่ยงไฮ้`,了:`แล้ว`},translationTh:`ถึงเวลาที่เราควรซื้อตั๋วไปเซี่ยงไฮ้แล้ว`,translationEn:`It is time for us to buy tickets to Shanghai.`,evidence:`Text 1 · หน้าเล่ม 48`,sourceRef:c}},{id:`h3l6-drive`,number:`02`,glyph:`灯`,title:`开车去高铁站`,titleTh:`ขับรถไปสถานีรถไฟความเร็วสูง`,titleEn:`Driving to the station`,place:`车上`,placeTh:`บนรถ`,...i(`drive`),imageAlt:{th:`ระหว่างขับรถไปสถานีรถไฟ`,zh:`开车去高铁站场景`,en:`Driving to the high-speed train station`},source:`Text 2 · หน้าเล่ม 49–50 · PDF หน้า 61–62`,sourcePage:`49–50`,sourceRef:l,context:`在车上，刘明开车送白家月和李文去高铁站。`,contextTh:`บนรถ หลิวหมิงขับรถไปส่งไป๋เจียเยว่กับหลี่เหวินที่สถานีรถไฟความเร็วสูง`,contextEn:`In the car, Liu Ming was driving Bai Jiayue and Li Wen to the high-speed train station.`,characters:[{role:`A`,profile:`liu`,noteTh:`คนขับที่เลี้ยวผิดเพราะรีบ`,noteZh:`因为着急走错路的司机`,noteEn:`The driver who took a wrong turn in a hurry`},{role:`B`,profile:`bai`,noteTh:`ผู้โดยสารที่สังเกตการจราจร`,noteZh:`注意路上交通情况的乘客`,noteEn:`The passenger watching the traffic`}],lines:[a(l,{role:`A`,speaker:`刘明`,hanzi:`过了前面的路口就到高铁站了。`,pinyin:`Guò le qiánmian de lùkǒu jiù dào gāotiězhàn le.`,en:`After the intersection ahead, we’ll reach the high-speed train station.`,th:`พอผ่านทางแยกข้างหน้าก็ถึงสถานีรถไฟความเร็วสูงแล้ว`,visual:{zh:`过了路口就到`,th:`ผ่านทางแยกก็ถึง`,focus:`34% center`}}),a(l,{role:`B`,speaker:`白家月`,hanzi:`我看见了。马上就到了，这条路车很多，您小心点儿。`,pinyin:`Wǒ kànjiàn le. Mǎshàng jiù dào le, zhè tiáo lù chē hěn duō, nín xiǎoxīn diǎnr.`,en:`I see it. We’re almost there. There are many cars on this road, so please be careful.`,th:`ฉันเห็นแล้ว ใกล้ถึงแล้ว ถนนสายนี้รถเยอะ คุณระวังหน่อย`,visual:{zh:`您小心点儿`,th:`คุณระวังหน่อย`,focus:`66% center`}}),a(l,{role:`A`,speaker:`刘明`,hanzi:`好，你们还有一个小时，应该不会迟到的。`,pinyin:`Hǎo, nǐmen hái yǒu yí ge xiǎoshí, yīnggāi bú huì chídào de.`,en:`Okay. You still have an hour, so you probably won’t be late.`,th:`ได้ พวกเธอยังมีเวลาอีกหนึ่งชั่วโมง น่าจะไม่สาย`,visual:{zh:`应该不会迟到`,th:`น่าจะไม่สาย`,focus:`36% center`}}),a(l,{role:`B`,speaker:`白家月`,hanzi:`我发现这条路车多，红绿灯也多。`,pinyin:`Wǒ fāxiàn zhè tiáo lù chē duō, hóng-lǜdēng yě duō.`,en:`I notice this road has lots of cars and lots of traffic lights.`,th:`ฉันสังเกตว่าถนนนี้รถเยอะ ไฟจราจรก็เยอะ`,visual:{zh:`车多，红绿灯也多`,th:`รถเยอะ ไฟก็เยอะ`,focus:`64% center`}}),a(l,{role:`A`,speaker:`刘明`,hanzi:`是啊，这条路我走过一次，后来再也不走了。`,pinyin:`Shì a, zhè tiáo lù wǒ zǒuguo yí cì, hòulái zài yě bù zǒu le.`,en:`Yes. I took this road once and never used it again afterward.`,th:`ใช่ ผมเคยใช้ถนนนี้ครั้งหนึ่ง หลังจากนั้นก็ไม่ใช้อีกเลย`,visual:{zh:`后来再也不走了`,th:`หลังจากนั้นไม่ใช้อีก`,focus:`38% center`}}),a(l,{role:`B`,speaker:`白家月`,hanzi:`那您今天为什么走了这条路？`,pinyin:`Nà nín jīntiān wèishénme zǒu le zhè tiáo lù?`,en:`Then why did you take this road today?`,th:`แล้ววันนี้ทำไมคุณถึงใช้ถนนเส้นนี้?`,visual:{zh:`为什么走这条路`,th:`ทำไมใช้ถนนนี้`,focus:`62% center`}}),a(l,{role:`A`,speaker:`刘明`,hanzi:`我一急就走错了。如果没走错，二十分钟以前就到了。`,pinyin:`Wǒ yì jí jiù zǒucuò le. Rúguǒ méi zǒucuò, èrshí fēnzhōng yǐqián jiù dào le.`,en:`I took a wrong turn when I got anxious. If I hadn’t, we would have arrived twenty minutes ago.`,th:`ผมรีบแล้วก็เลยเลี้ยวผิด ถ้าไม่ผิดทางคงถึงเมื่อยี่สิบนาทีก่อนแล้ว`,visual:{zh:`如果没走错`,th:`ถ้าไม่ผิดทาง`,focus:`40% center`}})],qte:{after:5,prompt:{th:`ทำไมหลิวหมิงจึงใช้ถนนเส้นนี้?`,zh:`刘明为什么走了这条路？`,en:`Why did Liu Ming take this road?`},options:[{value:`一急就走错了`,zh:`一急就走错了`,pinyin:`yì jí jiù zǒucuò le`,th:`รีบแล้วจึงเลี้ยวผิด`},{value:`这条路最近`,zh:`这条路最近`,pinyin:`zhè tiáo lù zuì jìn`,th:`ถนนนี้ใกล้ที่สุด`},{value:`红绿灯很少`,zh:`红绿灯很少`,pinyin:`hóng-lǜdēng hěn shǎo`,th:`ไฟจราจรน้อย`}],correct:`一急就走错了`,evidence:`刘明：我一急就走错了。`,evidenceTh:`หลิวหมิง: ผมรีบแล้วจึงเลี้ยวผิด`,sourceRef:l},builder:{prompt:{th:`เรียงประโยคสมมติ`,zh:`重组“如果……就……”句`,en:`Rebuild the 如果……就…… sentence`},answer:[`如果`,`没走错`,`二十分钟以前`,`就`,`到了`],tiles:[`到了`,`如果`,`就`,`没走错`,`二十分钟以前`],gloss:{如果:`ถ้าหาก`,没走错:`ไม่ผิดทาง`,二十分钟以前:`ยี่สิบนาทีก่อน`,就:`ก็`,到了:`ถึงแล้ว`},translationTh:`ถ้าไม่ผิดทาง ก็คงถึงเมื่อยี่สิบนาทีก่อนแล้ว`,translationEn:`If we had not taken a wrong turn, we would have arrived twenty minutes ago.`,evidence:`Text 2 · หน้าเล่ม 50`,sourceRef:l}},{id:`h3l6-station`,number:`03`,glyph:`检`,title:`在高铁站安检检票`,titleTh:`ตรวจความปลอดภัยและตั๋วที่สถานี`,titleEn:`Security and ticket checks`,place:`高铁站`,placeTh:`สถานีรถไฟความเร็วสูง`,...i(`station`),imageAlt:{th:`ไป๋เจียเยว่กับหลี่เหวินต่อแถวที่สถานี`,zh:`高铁站排队场景`,en:`Queuing at the high-speed train station`},source:`Text 3 · หน้าเล่ม 51 · PDF หน้า 63`,sourcePage:`51`,sourceRef:u,context:`在高铁站，李文和白家月排队安检、检票。`,contextTh:`ที่สถานีรถไฟความเร็วสูง หลี่เหวินกับไป๋เจียเยว่ต่อแถวตรวจความปลอดภัยและตั๋ว`,contextEn:`At the station, Li Wen and Bai Jiayue were queuing for security and ticket inspection.`,characters:[{role:`A`,profile:`bai`,noteTh:`ผู้ที่หูฟังแบตหมดและถามทางไปจุดตรวจตั๋ว`,noteZh:`耳机没电并询问检票地点的人`,noteEn:`The passenger with dead earphones asking where to check in`},{role:`B`,profile:`liWen`,noteTh:`ผู้มีพาวเวอร์แบงก์และอธิบายการสแกนหนังสือเดินทาง`,noteZh:`带充电宝并说明刷护照检票的人`,noteEn:`The passenger with a power bank explaining passport scanning`}],lines:[a(u,{role:`A`,speaker:`白家月`,hanzi:`李文，我的耳机没电了，你有充电宝吗？`,pinyin:`Lǐ Wén, wǒ de ěrjī méi diàn le, nǐ yǒu chōngdiànbǎo ma?`,en:`Li Wen, my earphones are out of power. Do you have a power bank?`,th:`หลี่เหวิน หูฟังฉันแบตหมด เธอมีพาวเวอร์แบงก์ไหม?`,visual:{zh:`耳机没电了`,th:`หูฟังแบตหมด`,focus:`34% center`}}),a(u,{role:`B`,speaker:`李文`,hanzi:`有，这些常用的东西我都放在包里了，我给你拿。`,pinyin:`Yǒu, zhèxiē chángyòng de dōngxi wǒ dōu fàng zài bāo li le, wǒ gěi nǐ ná.`,en:`Yes. I keep these commonly used things in my bag. I’ll get it for you.`,th:`มี ของที่ใช้ประจำพวกนี้ฉันใส่ไว้ในกระเป๋า เดี๋ยวหยิบให้`,visual:{zh:`都放在包里`,th:`ใส่ไว้ในกระเป๋าทั้งหมด`,focus:`66% center`}}),a(u,{role:`A`,speaker:`白家月`,hanzi:`前面的人越来越多。`,pinyin:`Qiánmian de rén yuèláiyuè duō.`,en:`There are more and more people ahead.`,th:`คนข้างหน้ายิ่งมากขึ้นเรื่อย ๆ`,visual:{zh:`越来越多`,th:`มากขึ้นเรื่อย ๆ`,focus:`36% center`}}),a(u,{role:`B`,speaker:`李文`,hanzi:`对，马上就进高铁站了。咱们一起走，别分开。`,pinyin:`Duì, mǎshàng jiù jìn gāotiězhàn le. Zánmen yìqǐ zǒu, bié fēnkāi.`,en:`Right. We’re about to enter the station. Let’s stay together and not separate.`,th:`ใช่ กำลังจะเข้าสถานีแล้ว เราไปด้วยกัน อย่าแยกกัน`,visual:{zh:`别分开`,th:`อย่าแยกกัน`,focus:`64% center`}}),a(u,{role:`A`,speaker:`白家月`,hanzi:`好，你检查一下，高铁票都拿好了吗？`,pinyin:`Hǎo, nǐ jiǎnchá yíxià, gāotiěpiào dōu ná hǎo le ma?`,en:`Okay. Check whether we have all the high-speed train tickets.`,th:`ได้ ลองตรวจดู ตั๋วรถไฟความเร็วสูงเอามาครบหรือยัง?`,visual:{zh:`检查一下`,th:`ตรวจดูหน่อย`,focus:`38% center`}}),a(u,{role:`B`,speaker:`李文`,hanzi:`不用拿票，刷护照就能检票进站。`,pinyin:`Búyòng ná piào, shuā hùzhào jiù néng jiǎnpiào jìnzhàn.`,en:`We don’t need tickets. Scanning our passports lets us pass ticket inspection and enter.`,th:`ไม่ต้องถือตั๋ว สแกนหนังสือเดินทางก็ตรวจตั๋วเข้าสถานีได้`,visual:{zh:`刷护照就能进站`,th:`สแกนหนังสือเดินทางก็เข้าได้`,focus:`62% center`}}),a(u,{role:`A`,speaker:`白家月`,hanzi:`去哪里检票？`,pinyin:`Qù nǎli jiǎnpiào?`,en:`Where do we go for ticket inspection?`,th:`ไปตรวจตั๋วที่ไหน?`,visual:{zh:`去哪里检票`,th:`ตรวจตั๋วที่ไหน`,focus:`40% center`}}),a(u,{role:`B`,speaker:`李文`,hanzi:`检票口在二层，我们一会儿坐电梯上去。`,pinyin:`Jiǎnpiàokǒu zài èr céng, wǒmen yíhuìr zuò diàntī shàngqu.`,en:`The ticket gate is on the second floor. We’ll take the elevator up shortly.`,th:`จุดตรวจตั๋วอยู่ชั้นสอง อีกสักครู่เรานั่งลิฟต์ขึ้นไป`,visual:{zh:`检票口在二层`,th:`จุดตรวจอยู่ชั้นสอง`,focus:`42% center`}})],qte:{after:5,prompt:{th:`ทั้งคู่ใช้อะไรตรวจตั๋วเข้าสถานี?`,zh:`他们用什么检票进站？`,en:`What do they use to pass ticket inspection?`},options:[{value:`护照`,zh:`护照`,pinyin:`hùzhào`,th:`หนังสือเดินทาง`},{value:`手机App`,zh:`手机App`,pinyin:`shǒujī App`,th:`แอปมือถือ`},{value:`充电宝`,zh:`充电宝`,pinyin:`chōngdiànbǎo`,th:`พาวเวอร์แบงก์`}],correct:`护照`,evidence:`李文：刷护照就能检票进站。`,evidenceTh:`หลี่เหวิน: สแกนหนังสือเดินทางก็ตรวจตั๋วเข้าสถานีได้`,sourceRef:u},builder:{prompt:{th:`เรียงประโยคบอกว่าคนมากขึ้นเรื่อย ๆ`,zh:`重组“越来越”句`,en:`Rebuild the 越来越 sentence`},answer:[`前面`,`的`,`人`,`越来越`,`多`],tiles:[`人`,`多`,`越来越`,`的`,`前面`],gloss:{前面:`ข้างหน้า`,的:`ของ / ที่`,人:`คน`,越来越:`ยิ่งขึ้นเรื่อย ๆ`,多:`มาก`},translationTh:`คนข้างหน้ามากขึ้นเรื่อย ๆ`,translationEn:`There are more and more people ahead.`,evidence:`Text 3 · หน้าเล่ม 51`,sourceRef:u}}],f={id:`hsk3-l6`,slug:`lesson-6`,level:`hsk3`,number:6,featured:!1,sourceRef:r,source:{title:`新HSK教程 3 · New HSK Course 3`,lesson:`Lesson 6 · 高铁上还可以点外卖`,printedPages:`47–55`,pdfPages:`59–67`,file:`hsk3.pdf`,sourceRef:r},title:{zh:`高铁上还可以点外卖`,pinyin:`Gāotiě shang hái kěyǐ diǎn wàimài`,en:`You can even order takeout on a high-speed train`,thAid:`บนรถไฟความเร็วสูงยังสั่งอาหารเดลิเวอรีได้ด้วย`},summary:{zh:`计划坐高铁、开车去车站并排队检票，学习“该……了”、“如果……就……”和“越来越”。`,en:`Plan a high-speed train trip, drive to the station, and pass ticket inspection while learning 该……了, 如果……就……, and 越来越.`,thAid:`วางแผนนั่งรถไฟ ไปสถานี และตรวจตั๋ว พร้อมฝึก 该……了, 如果……就…… และ 越来越`},translationPolicy:{kind:`editorial-aid`,labelTh:`คำแปลไทยเพื่อช่วยเรียน เรียบเรียงจากต้นฉบับ`},objectives:[{zh:`能听懂并介绍交通方式的特点和出行体验。`,en:`Understand and introduce the characteristics of transportation and travel experiences.`,thAid:`ฟังเข้าใจและแนะนำลักษณะของพาหนะกับประสบการณ์เดินทาง`,sourceRef:n(`47`,`59`)},{zh:`能听懂并使用“如果”表达假设的情况和结果。`,en:`Understand and use 如果 to express hypothetical situations and results.`,thAid:`เข้าใจและใช้ 如果 เพื่อบอกสมมติฐานและผลลัพธ์`,sourceRef:n(`47`,`59`)},{zh:`掌握“越来越”短语，能描述事物的变化趋势。`,en:`Master 越来越 to describe changing trends.`,thAid:`ใช้ 越来越 เพื่อบอกแนวโน้มการเปลี่ยนแปลง`,sourceRef:n(`47`,`59`)},{zh:`了解中国的现代交通方式——高铁。`,en:`Understand China’s modern means of transportation—high-speed rail.`,thAid:`เรียนรู้ระบบคมนาคมสมัยใหม่ของจีน ได้แก่ รถไฟความเร็วสูง`,sourceRef:n(`47`,`59`)}],contents:[{number:`00`,title:`目标与热身`,titleTh:`เป้าหมายและการเตรียมบท`,detail:`Objectives · Warm-Up`,pages:`47`,route:`/home/hsk3/lesson-6/preface/`,sourceRef:n(`47`,`59`)},{number:`01`,title:`商量坐高铁去上海`,titleTh:`วางแผนนั่งรถไฟไปเซี่ยงไฮ้`,detail:`Text 1 · New Words 1–4`,pages:`48–49`,scene:1,sourceRef:n(`48-49`,`60-61`)},{number:`02`,title:`开车去高铁站`,titleTh:`ขับรถไปสถานี`,detail:`Text 2 · New Words 5–12`,pages:`49–50`,scene:2,sourceRef:n(`49-50`,`61-62`)},{number:`03`,title:`在高铁站安检检票`,titleTh:`ตรวจความปลอดภัยและตั๋ว`,detail:`Text 3 · New Words 13–21`,pages:`51–52`,scene:3,sourceRef:n(`51-52`,`63-64`)},{number:`04`,title:`高铁旅行、练习与活动`,titleTh:`การเดินทาง แบบฝึก และกิจกรรม`,detail:`Text 4 · Exercises · Activity`,pages:`52–55`,sourceRef:n(`52-55`,`64-67`)}],vocabulary:s,grammarFocus:[{title:`固定格式“该……了”`,titleEn:`Fixed Pattern 该……了`,explanationZh:`“该……了”表示到了需要做某事的时候，多在口语中使用。`,explanationEn:`该……了 indicates that it is time to do something and is often used in colloquial speech.`,thAid:`该……了 ใช้บอกว่าถึงเวลาที่ต้องทำบางสิ่ง มักใช้ในภาษาพูด`,examples:[`咱们该买去上海的票了。`,`八点了，该上课了。`,`已经很晚了，我该睡觉了。`],sourceRef:n(`49`,`61`)},{title:`假设复句“如果……，就……”`,titleEn:`Hypothetical Complex Sentence 如果……就……`,explanationZh:`“如果”后的分句表示假设，“就”后的分句表示在这种假设下产生的结果。`,explanationEn:`The clause after 如果 gives a hypothesis, and the clause with 就 gives its result.`,thAid:`ประโยคหลัง 如果 เป็นเงื่อนไขสมมติ ส่วนประโยคที่มี 就 เป็นผลลัพธ์`,examples:[`如果没走错，二十分钟以前就到了。`,`如果你需要帮忙，就给我打电话。`,`如果有时间，我就去上海玩几天。`],sourceRef:n(`50`,`62`)},{title:`固定短语“越来越”`,titleEn:`Set Phrase 越来越`,explanationZh:`“越来越”后加形容词或心理动词，表示随着时间推移在程度上发生变化。`,explanationEn:`越来越 is followed by an adjective or psychological verb to show a change in degree over time.`,thAid:`越来越 วางหน้าคุณศัพท์หรือกริยาความรู้สึก เพื่อบอกระดับที่เปลี่ยนขึ้นเรื่อย ๆ`,examples:[`前面的人越来越多。`,`我越来越喜欢这里的生活了。`,`她越来越高，也越来越漂亮了。`],sourceRef:n(`52`,`64`)}],characters:o,scenes:d};export{f as LESSON_HSK3_L6};